/**
 * Checks whether a string is a raw UUID, hex hash, or generic camera/clipboard noise filename.
 */
export function isUuidOrNoiseName(raw?: string | null): boolean {
  const s = (raw || '').trim();
  if (!s) return true;
  // Matches UUID patterns anywhere in the string (with hyphens, underscores, or spaces)
  if (/[0-9a-f]{8}[\s_-]+[0-9a-f]{4}[\s_-]+[0-9a-f]{4}[\s_-]+[0-9a-f]{4}[\s_-]+[0-9a-f]{12}/i.test(s)) {
    return true;
  }
  // Matches 3+ space/hyphen-separated hex blocks like "9d6c75de 3d44 4100..."
  if (/\b[0-9a-f]{6,12}[\s_-]+[0-9a-f]{4,12}[\s_-]+[0-9a-f]{4,12}/i.test(s)) {
    return true;
  }
  // Matches contiguous 16+ hex hash strings
  if (/^[0-9a-f]{16,}$/i.test(s.replace(/[\s_-]/g, ''))) {
    return true;
  }
  // Matches camera / clipboard / temp filenames
  if (
    /^(cmpvs|img|dsc|dcim|screenshot|screen\s*shot|whatsapp\s*image|image|photo|picture|pic|untitled|download|file|capture|clipboard|paste|comfyui|pixal3d|trellis|temp|output|asset)[\s_()-]*\d*/i.test(
      s
    )
  ) {
    return true;
  }
  return false;
}

/**
 * Infers the stage category (`'human' | 'creature' | 'prop'`) and a clean human-readable display name
 * from any prompt or filename.
 */
export function inferSubjectCategoryAndCleanName(
  rawInput?: string | null,
  fallbackCategory: 'human' | 'creature' | 'prop' = 'prop'
): {
  category: 'human' | 'creature' | 'prop';
  cleanName: string;
  isNoiseOrUuid: boolean;
} {
  const raw = (rawInput || '')
    .replace(/\.[^.]+$/, '')
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const isNoise = isUuidOrNoiseName(raw);
  const text = isNoise ? '' : raw.toLowerCase();

  let category: 'human' | 'creature' | 'prop' = fallbackCategory;
  if (text) {
    if (RIGID_PROP_KEYWORDS_REGEX.test(text) || RIGID_PROP_ARABIC_REGEX.test(text)) {
      category = 'prop';
    } else if (
      /\b(dog|hound|wolf|canine|cat|feline|lion|tiger|panther|leopard|cheetah|horse|stallion|pony|stag|deer|elk|bear|boar|bull|cow|sheep|goat|fox|rabbit|camel|elephant|rhino|hippo|dinosaur|raptor|rex|dragon|wyvern|griffin|beast|quadruped|snake|serpent|creature|animal)\b/i.test(
        text
      ) ||
      /(كلب|ذئب|قط|حصان|فرس|أسد|نمر|غزال|وعل|دب|جمل|فيل|تنين|وحش|حيوان|ثعبان|أفعى|مخلوق)/.test(text)
    ) {
      category = 'creature';
    } else if (
      /\b(character|person|man|woman|boy|girl|child|human|actor|actress|hero|heroine|villain|knight|warrior|archer|scout|detective|soldier|doctor|pilot|wizard|mage|king|queen|prince|princess|pirate|cowboy|astronaut|ninja|samurai|guard|robot|android|cyborg|mech|biped|goblin|orc|elf|dwarf|zombie|skeleton|alien)\b/i.test(
        text
      ) ||
      /(شخصية|رجل|امرأة|ولد|بنت|طفل|إنسان|بطل|فارس|محارب|نينجا|طبيب|محقق|شرطي|جندي|ممثل|ساحر|ملك|ملكة|روبوت|آلي)/.test(
        text
      )
    ) {
      category = 'human';
    }
  }

  const fallbackLabel =
    category === 'prop'
      ? '3D Object'
      : category === 'creature'
      ? '3D Creature'
      : 'Hero Character';

  const cleanName = !isNoise && raw.length > 0 ? raw.slice(0, 42) : fallbackLabel;
  return {
    category,
    cleanName,
    isNoiseOrUuid: isNoise,
  };
}

/**
 * Resolves `'auto'` rig type into a concrete `ResolvedRigType` based on semantic hints
 * and 3D bounding-box / silhouette proportions.
 */
export function resolveAutoRigType(
  sceneRoot: THREE.Object3D,
  options: AutoRigOptions = {}
): ResolvedRigType {
  if (options.rigType && options.rigType !== 'auto') {
    return options.rigType;
  }

  const cat = (options.categoryHint || '').toLowerCase();
  const cleanHintName = isUuidOrNoiseName(options.nameHint) ? '' : options.nameHint || '';
  const text = `${cleanHintName} ${options.promptHint || ''} ${cat}`.toLowerCase();

  // 1. Flexible Spine props / nature / serpentine entities
  // Checked first so flexible props (e.g., categoryHint: 'prop', nameHint: 'Weeping Willow Tree')
  // get a multi-bone spine_flex chain before falling through to generic rigid_prop.
  if (
    /\b(snake|serpent|worm|tentacle|eel|cobra|viper|python|tree|palm|pine|oak|willow|plant|fern|vine|rope|cable|chain|flag|banner|cape|cloak|curtain|tail)\b/i.test(
      text
    ) ||
    /(شجرة|نخلة|نبات|علم|راية|حبل|ثعبان|أفعى|مجس)/.test(text)
  ) {
    return 'spine_flex';
  }

  // 2. Explicit Rigid Prop / Headwear / Clothing / Vehicle / Architecture / Weapon / Furniture keywords
  // Checked BEFORE generic categoryHint so items like a "baseball cap", "helmet", "chair", or "car"
  // are never misclassified as a 19-bone humanoid even if the category button was left on default.
  if (
    cat === 'vehicle' ||
    cat === 'architecture' ||
    cat === 'furniture' ||
    cat === 'weapons' ||
    cat === 'props' ||
    cat === 'prop' ||
    cat === 'building' ||
    RIGID_PROP_KEYWORDS_REGEX.test(text) ||
    RIGID_PROP_ARABIC_REGEX.test(text)
  ) {
    return 'rigid_prop';
  }

  // 3. Explicit Quadruped / Animal keywords
  if (
    cat === 'creature' ||
    cat === 'animal' ||
    cat === 'quadruped' ||
    /\b(dog|hound|wolf|canine|cat|feline|lion|tiger|panther|leopard|cheetah|horse|stallion|pony|stag|deer|elk|bear|boar|bull|cow|sheep|goat|fox|rabbit|camel|elephant|rhino|hippo|dinosaur|raptor|rex|dragon|wyvern|griffin|beast|quadruped)\b/i.test(
      text
    ) ||
    /(كلب|ذئب|قط|حصان|فرس|أسد|نمر|غزال|وعل|دب|جمل|فيل|تنين|وحش|حيوان)/.test(text)
  ) {
    return 'quadruped';
  }

  // 4. Measure 3D Geometry Bounding-Box Aspect Proportions BEFORE trusting a default 'human' categoryHint!
  // A standing humanoid biped is vertically oriented (height Y significantly exceeds depth/width).
  // Squat/flat/dome/horizontal meshes (such as a baseball cap, shoe, car, crate, or table) have
  // low vertical aspect ratios and must NOT be stuffed with a 19-bone humanoid skeleton.
  sceneRoot.updateMatrixWorld(true);
  const bbox = new THREE.Box3().setFromObject(sceneRoot);
  if (!bbox.isEmpty()) {
    const size = bbox.getSize(new THREE.Vector3());
    const maxHoriz = Math.max(size.x, size.z);
    const minHoriz = Math.min(size.x, size.z);

    if (size.y > 1e-4 && maxHoriz > 1e-4) {
      // Squat / dome / flat / wide object (e.g. baseball cap, helmet, car, table, box):
      // Height is less than 88% of max horizontal span, OR height is less than 130% of the narrower horizontal axis
      const isSquatOrCompactObject =
        size.y < maxHoriz * 0.88 || (size.y < maxHoriz * 1.12 && size.y < minHoriz * 1.32);

      if (isSquatOrCompactObject) {
        return 'rigid_prop';
      }
    }
  }

  // 5. Explicit Humanoid / Biped Character keywords or category
  if (
    cat === 'character' ||
    cat === 'human' ||
    /\b(character|person|man|woman|boy|girl|child|human|actor|actress|hero|heroine|villain|knight|warrior|archer|scout|detective|soldier|doctor|pilot|wizard|mage|king|queen|prince|princess|pirate|cowboy|astronaut|ninja|samurai|guard|robot|android|cyborg|mech|biped|goblin|orc|elf|dwarf|zombie|skeleton|alien|monster)\b/i.test(
      text
    ) ||
    /(شخصية|رجل|امرأة|ولد|بنت|طفل|إنسان|بطل|فارس|محارب|نينجا|طبيب|محقق|شرطي|جندي|ممثل|ساحر|ملك|ملكة|روبوت|آلي)/.test(text)
  ) {
    return 'humanoid';
  }

  // 6. Fallback Geometry Proportions Check
  if (!bbox.isEmpty()) {
    const size = bbox.getSize(new THREE.Vector3());
    const maxHoriz = Math.max(size.x, size.z);
    if (size.y > maxHoriz * 1.15) {
      return 'humanoid';
    }
    if (maxHoriz > size.y * 1.15 && Math.min(size.x, size.z) < maxHoriz * 0.65) {
      return 'quadruped';
    }
    return 'rigid_prop';
  }

  return 'humanoid';
}

/**
 * Collects a fast, evenly strided sample of vertex positions in `sceneRoot` local space.
 */
function sampleSceneVerticesLocal(sceneRoot: THREE.Object3D, maxSamples = 10000): THREE.Vector3[] {
  sceneRoot.updateMatrixWorld(true);
  const invRootMatrix = new THREE.Matrix4().copy(sceneRoot.matrixWorld).invert();

  let totalVertices = 0;
  const meshes: { mesh: THREE.Mesh; count: number; localMat: THREE.Matrix4 }[] = [];

  sceneRoot.traverse((child) => {
    if ((child as THREE.Mesh).isMesh && !child.name.startsWith('__')) {
      const mesh = child as THREE.Mesh;
      const posAttr = mesh.geometry?.attributes?.position;
      if (posAttr && posAttr.count > 0) {
        const localMat = new THREE.Matrix4().multiplyMatrices(invRootMatrix, mesh.matrixWorld);
        meshes.push({ mesh, count: posAttr.count, localMat });
        totalVertices += posAttr.count;
      }
    }
  });

  if (totalVertices === 0) return [];

  const stride = Math.max(1, Math.floor(totalVertices / maxSamples));
  const samples: THREE.Vector3[] = [];
  const tmp = new THREE.Vector3();

  for (const { mesh, count, localMat } of meshes) {
    const posAttr = mesh.geometry.attributes.position;
    for (let i = 0; i < count; i += stride) {
      tmp.fromBufferAttribute(posAttr, i).applyMatrix4(localMat);
      if (Number.isFinite(tmp.x) && Number.isFinite(tmp.y) && Number.isFinite(tmp.z)) {
        samples.push(tmp.clone());
      }
    }
  }

  return samples;
}

/**
 * Scans vertex slices of `sceneRoot` to automatically fit `RigLandmarks` to the actual
 * silhouette of a Humanoid (T-pose, A-pose, or Relaxed stand) or Quadruped mesh.
 */
export function detectMeshRigLandmarks(
  sceneRoot: THREE.Object3D,
  rigType: ResolvedRigType = 'humanoid',
  overrides?: Partial<RigLandmarks>
): RigLandmarks {
  let primaryGeom: THREE.BufferGeometry | null = null;
  sceneRoot.traverse((child) => {
    if (!primaryGeom && (child as THREE.Mesh).isMesh && !child.name.startsWith('__')) {
      primaryGeom = (child as THREE.Mesh).geometry || null;
    }
  });
  const cacheKey = `__cachedLandmarks_${rigType}`;
  if (primaryGeom && (primaryGeom as THREE.BufferGeometry).userData?.[cacheKey]) {
    const cachedBase = (primaryGeom as THREE.BufferGeometry).userData[cacheKey] as RigLandmarks;
    return { ...cachedBase, ...overrides };
  }

  const samples = sampleSceneVerticesLocal(sceneRoot);
  if (samples.length < 20) {
    return { ...DEFAULT_HUMANOID_LANDMARKS, ...overrides };
  }

  // Compute bounds in sceneRoot local space
  const bbox = new THREE.Box3();
  for (const p of samples) bbox.expandByPoint(p);
  const size = bbox.getSize(new THREE.Vector3());
  const center = bbox.getCenter(new THREE.Vector3());
  const H = Math.max(0.001, size.y);
  const minY = bbox.min.y;

  // Normalize all sample points into height-normalized coordinates:
  // ny in [0..1], nx and nz centered at bbox center X/Z and scaled by 1/H
  const normPts = samples.map((p) => ({
    x: (p.x - center.x) / H,
    y: THREE.MathUtils.clamp((p.y - minY) / H, 0, 1),
    z: (p.z - center.z) / H,
  }));

  if (rigType === 'quadruped') {
    // Determine if the quadruped's length is along Z or X
    const spanX = size.x / H;
    const spanZ = size.z / H;
    const isLengthAlongZ = spanZ >= spanX * 0.85;

    // Find which end (+Z or -Z) has the higher head profile in upper Y (> 0.62)
    let posEndTopCount = 0;
    let negEndTopCount = 0;
    for (const p of normPts) {
      const foreAft = isLengthAlongZ ? p.z : p.x;
      if (p.y > 0.65) {
        if (foreAft >= 0) posEndTopCount++;
        else negEndTopCount++;
      }
    }
    const dirSign = posEndTopCount >= negEndTopCount ? 1 : -1;
    const halfLen = (isLengthAlongZ ? spanZ : spanX) * 0.5;
    const halfWid = (isLengthAlongZ ? spanX : spanZ) * 0.5;

    const legX = THREE.MathUtils.clamp(halfWid * 0.52, 0.06, 0.22);
    const frontZ = dirSign * THREE.MathUtils.clamp(halfLen * 0.52, 0.14, 0.45);
    const backZ = -dirSign * THREE.MathUtils.clamp(halfLen * 0.52, 0.14, 0.45);

    const landmarks: RigLandmarks = {
      ...DEFAULT_HUMANOID_LANDMARKS,
      hipsY: 0.58,
      spineY: 0.60,
      chestY: 0.62,
      neckY: 0.70,
      headY: 0.80,
      quadSpineY: 0.58,
      quadNeckPos: isLengthAlongZ
        ? [0, 0.68, dirSign * THREE.MathUtils.clamp(halfLen * 0.56, 0.16, 0.45)]
        : [dirSign * THREE.MathUtils.clamp(halfLen * 0.56, 0.16, 0.45), 0.68, 0],
      quadHeadPos: isLengthAlongZ
        ? [0, 0.78, dirSign * THREE.MathUtils.clamp(halfLen * 0.76, 0.24, 0.58)]
        : [dirSign * THREE.MathUtils.clamp(halfLen * 0.76, 0.24, 0.58), 0.78, 0],
      quadTailPos: isLengthAlongZ
        ? [0, 0.56, -dirSign * THREE.MathUtils.clamp(halfLen * 0.82, 0.24, 0.60)]
        : [-dirSign * THREE.MathUtils.clamp(halfLen * 0.82, 0.24, 0.60), 0.56, 0],
      quadFrontLegX: legX,
      quadFrontLegZ: frontZ,
      quadBackLegX: legX,
      quadBackLegZ: backZ,
      isLengthAlongZ,
      detectedStance: 'quadruped',
    };
    if (primaryGeom) {
      (primaryGeom as THREE.BufferGeometry).userData[cacheKey] = landmarks;
    }
    return { ...landmarks, ...overrides };
  }

  // HUMANOID SILHOUETTE SLICE SCANNER
  // 1. Measure core waist/belly half-width in ny ∈ [0.54, 0.66]
  const waistAbsX: number[] = [];
  for (const p of normPts) {
    if (p.y >= 0.54 && p.y <= 0.66) {
      waistAbsX.push(Math.abs(p.x));
    }
  }
  waistAbsX.sort((a, b) => a - b);
  const waistP60 = waistAbsX.length > 0 ? waistAbsX[Math.floor(waistAbsX.length * 0.60)] : 0.095;
  const torsoHalfW = THREE.MathUtils.clamp(waistP60, 0.065, 0.145);

  // 2. Find neck constriction in ny ∈ [0.77, 0.86]
  let neckY = 0.83;
  let minNeckSpan = Infinity;
  for (let band = 0; band < 6; band++) {
    const y0 = 0.77 + band * 0.015;
    const y1 = y0 + 0.02;
    const bandX = normPts.filter((p) => p.y >= y0 && p.y <= y1 && Math.abs(p.x) < torsoHalfW * 1.4).map((p) => Math.abs(p.x));
    if (bandX.length >= 5) {
      bandX.sort((a, b) => a - b);
      const p85 = bandX[Math.floor(bandX.length * 0.85)];
      if (p85 < minNeckSpan) {
        minNeckSpan = p85;
        neckY = (y0 + y1) * 0.5;
      }
    }
  }
  neckY = THREE.MathUtils.clamp(neckY, 0.79, 0.86);
  const headY = THREE.MathUtils.clamp(neckY + 0.065, 0.86, 0.93);
  const shoulderY = THREE.MathUtils.clamp(neckY - 0.045, 0.74, 0.81);
  const chestY = THREE.MathUtils.clamp(shoulderY - 0.055, 0.68, 0.76);
  const hipsY = 0.52;
  const spineY = (hipsY + chestY) * 0.5;

  // 3. Detect Shoulder Span and Arm Trajectory (T-pose vs A-pose vs Relaxed Stand)
  const shoulderSpanX = THREE.MathUtils.clamp(torsoHalfW * 1.18, 0.12, 0.18);
  const armCandidates = normPts.filter(
    (p) => p.y >= 0.42 && p.y <= 0.84 && Math.abs(p.x) > shoulderSpanX * 1.05
  );

  let detectedStance: RigLandmarks['detectedStance'] = 'a-pose';
  let elbowPos: [number, number, number] = [shoulderSpanX + 0.075, shoulderY - 0.13, -0.01];
  let wristPos: [number, number, number] = [shoulderSpanX + 0.135, shoulderY - 0.26, 0.02];

  if (armCandidates.length >= 12) {
    // Sort arm candidates by |x| descending to find the outer arm tip (wrist/hand)
    const sortedByOutX = [...armCandidates].sort((a, b) => Math.abs(b.x) - Math.abs(a.x));
    const topOuterCount = Math.max(5, Math.floor(sortedByOutX.length * 0.12));
    const outerTipSlice = sortedByOutX.slice(0, topOuterCount);

    let tipX = 0;
    let tipY = 0;
    let tipZ = 0;
    for (const p of outerTipSlice) {
      tipX += Math.abs(p.x);
      tipY += p.y;
      tipZ += p.z;
    }
    tipX /= outerTipSlice.length;
    tipY /= outerTipSlice.length;
    tipZ /= outerTipSlice.length;

    if (tipY >= 0.71 && tipX >= 0.30) {
      // T-Pose
      detectedStance = 't-pose';
      const wx = THREE.MathUtils.clamp(tipX * 0.88, 0.28, 0.46);
      const wy = THREE.MathUtils.clamp(tipY, 0.72, 0.83);
      const wz = THREE.MathUtils.clamp(tipZ, -0.08, 0.08);
      wristPos = [wx, wy, wz];
      elbowPos = [
        (shoulderSpanX + wx) * 0.5,
        (shoulderY + wy) * 0.5,
        wz * 0.5 - 0.01,
      ];
    } else if (tipX >= shoulderSpanX + 0.07 && tipY >= 0.46) {
      // A-Pose (or angled arms)
      detectedStance = tipX >= 0.23 ? 'a-pose' : 'relaxed';
      const wx = THREE.MathUtils.clamp(tipX * 0.88, shoulderSpanX + 0.04, 0.42);
      const wy = THREE.MathUtils.clamp(tipY + 0.02, 0.46, 0.72);
      const wz = THREE.MathUtils.clamp(tipZ, -0.10, 0.12);
      wristPos = [wx, wy, wz];

      // Find mid-arm elbow centroid around mid-height between shoulderY and wy
      const midY = (shoulderY + wy) * 0.5;
      const midArmPts = armCandidates.filter((p) => Math.abs(p.y - midY) <= 0.06);
      if (midArmPts.length >= 4) {
        midArmPts.sort((a, b) => Math.abs(b.x) - Math.abs(a.x));
        const outerMid = midArmPts.slice(0, Math.max(3, Math.floor(midArmPts.length * 0.4)));
        const ex = outerMid.reduce((s, p) => s + Math.abs(p.x), 0) / outerMid.length;
        const ez = outerMid.reduce((s, p) => s + p.z, 0) / outerMid.length;
        elbowPos = [
          THREE.MathUtils.clamp(ex * 0.9, shoulderSpanX + 0.02, wx),
          midY,
          THREE.MathUtils.clamp(ez, -0.10, 0.10),
        ];
      } else {
        elbowPos = [
          (shoulderSpanX + wx) * 0.5,
          midY,
          wz * 0.5 - 0.01,
        ];
      }
    } else {
      // Arms hanging closely along the sides
      detectedStance = 'relaxed';
      const sideArmX = THREE.MathUtils.clamp(shoulderSpanX + 0.035, 0.15, 0.24);
      elbowPos = [sideArmX, 0.63, -0.01];
      wristPos = [sideArmX + 0.01, 0.50, 0.02];
    }
  }

  // 4. Detect Leg & Ankle Separation in lower body
  const kneeBand = normPts.filter((p) => p.y >= 0.23 && p.y <= 0.31 && Math.abs(p.x) > 0.015);
  const ankleBand = normPts.filter((p) => p.y >= 0.04 && p.y <= 0.12 && Math.abs(p.x) > 0.015);

  let kneeX = 0.09;
  let kneeZ = 0.01;
  if (kneeBand.length >= 6) {
    kneeX = THREE.MathUtils.clamp(
      kneeBand.reduce((s, p) => s + Math.abs(p.x), 0) / kneeBand.length,
      0.055,
      0.18
    );
    kneeZ = THREE.MathUtils.clamp(
      kneeBand.reduce((s, p) => s + p.z, 0) / kneeBand.length,
      -0.08,
      0.08
    );
  }

  let ankleX = kneeX;
  let ankleZ = 0.0;
  if (ankleBand.length >= 6) {
    ankleX = THREE.MathUtils.clamp(
      ankleBand.reduce((s, p) => s + Math.abs(p.x), 0) / ankleBand.length,
      0.055,
      0.20
    );
    ankleZ = THREE.MathUtils.clamp(
      ankleBand.reduce((s, p) => s + p.z, 0) / ankleBand.length,
      -0.08,
      0.08
    );
  }

  const hipSpanX = THREE.MathUtils.clamp((kneeX + torsoHalfW * 0.75) * 0.5, 0.065, 0.135);

  const detectedBase: RigLandmarks = {
    hipsY,
    spineY,
    chestY,
    neckY,
    headY,
    shoulderSpanX,
    shoulderY,
    elbowPos,
    wristPos,
    hipSpanX,
    kneePos: [kneeX, 0.27, kneeZ],
    anklePos: [ankleX, 0.055, ankleZ],
    detectedStance,
  };
  if (primaryGeom) {
    (primaryGeom as THREE.BufferGeometry).userData[cacheKey] = detectedBase;
  }
  return {
    ...detectedBase,
    ...overrides,
  };
}

interface BoneSegmentDef {
  boneIndex: number;
  boneName: HumanoidBone;
  start: THREE.Vector3;
  end: THREE.Vector3;
  radius: number;
  side: 'left' | 'right' | 'center';
  region: 'torso' | 'head' | 'arm' | 'leg';
}

/**
 * Builds a 19-bone `HumanoidRig` fitted to `landmarks` (or a Quadruped / Spine-Flex rig mapped
 * onto `HumanoidRig` bones) at model height `H`.
 */
function buildAdaptiveRigSkeleton(
  rigType: ResolvedRigType,
  H: number,
  landmarks: RigLandmarks
): { rig: HumanoidRig; segments: BoneSegmentDef[] } {
  const root = new THREE.Group();
  root.name = 'AutoRiggedRoot';

  const bonesMap = new Map<HumanoidBone, THREE.Bone>();
  const restPositions = new Map<HumanoidBone, THREE.Vector3>();
  const restRotations = new Map<HumanoidBone, THREE.Quaternion>();
  const bonesList: THREE.Bone[] = [];

  // World-space (relative to `root`) target positions for each of the 19 canonical bones
  const worldPos = new Map<HumanoidBone, THREE.Vector3>();
  const parentMap = new Map<HumanoidBone, HumanoidBone | undefined>();

  if (rigType === 'quadruped') {
    const sy = (landmarks.quadSpineY ?? 0.58) * H;
    const alongZ = landmarks.isLengthAlongZ !== false;
    const neckP = landmarks.quadNeckPos ?? (alongZ ? [0, 0.68, 0.28] : [0.28, 0.68, 0]);
    const headP = landmarks.quadHeadPos ?? (alongZ ? [0, 0.78, 0.42] : [0.42, 0.78, 0]);
    const tailP = landmarks.quadTailPos ?? (alongZ ? [0, 0.56, -0.45] : [-0.45, 0.56, 0]);
    const flX = (landmarks.quadFrontLegX ?? 0.11) * H;
    const flZ = (landmarks.quadFrontLegZ ?? 0.24) * H;
    const blX = (landmarks.quadBackLegX ?? 0.11) * H;
    const blZ = (landmarks.quadBackLegZ ?? -0.24) * H;
    const midZ = (flZ + blZ) * 0.5;
    const pt = (lat: number, y: number, foreAft: number) =>
      alongZ ? new THREE.Vector3(lat, y, foreAft) : new THREE.Vector3(foreAft, y, lat);

    worldPos.set('Hips', pt(0, sy, blZ * 0.65));
    worldPos.set('Spine', pt(0, sy, midZ));
    worldPos.set('Chest', pt(0, sy + 0.02 * H, flZ * 0.75));
    worldPos.set('Neck', new THREE.Vector3(neckP[0] * H, neckP[1] * H, neckP[2] * H));
    worldPos.set('Head', new THREE.Vector3(headP[0] * H, headP[1] * H, headP[2] * H));

    // Front Left Leg mapped to LeftShoulder -> LeftArm -> LeftForeArm -> LeftHand
    worldPos.set('LeftShoulder', pt(flX * 0.6, sy, flZ));
    worldPos.set('LeftArm', pt(flX, sy * 0.88, flZ));
    worldPos.set('LeftForeArm', pt(flX, sy * 0.46, flZ));
    worldPos.set('LeftHand', pt(flX, 0.05 * H, flZ + 0.02 * H));

    // Front Right Leg mapped to RightShoulder -> RightArm -> RightForeArm -> RightHand
    worldPos.set('RightShoulder', pt(-flX * 0.6, sy, flZ));
    worldPos.set('RightArm', pt(-flX, sy * 0.88, flZ));
    worldPos.set('RightForeArm', pt(-flX, sy * 0.46, flZ));
    worldPos.set('RightHand', pt(-flX, 0.05 * H, flZ + 0.02 * H));

    // Back Left Leg mapped to LeftUpLeg -> LeftLeg -> LeftFoot
    worldPos.set('LeftUpLeg', pt(blX, sy * 0.88, blZ));
    worldPos.set('LeftLeg', pt(blX, sy * 0.46, blZ - 0.02 * H));
    worldPos.set('LeftFoot', pt(blX, 0.05 * H, blZ));

    // Back Right Leg mapped to RightUpLeg -> RightLeg -> RightFoot
    worldPos.set('RightUpLeg', pt(-blX, sy * 0.88, blZ));
    worldPos.set('RightLeg', pt(-blX, sy * 0.46, blZ - 0.02 * H));
    worldPos.set('RightFoot', pt(-blX, 0.05 * H, blZ));

    // Add an explicit Tail bone under Hips for quadruped tail wagging
    const tailBone = new THREE.Bone();
    tailBone.name = 'tail_bone';
    tailBone.userData.role = 'tail';
    const hipsPos = worldPos.get('Hips')!;
    tailBone.position.set(
      tailP[0] * H - hipsPos.x,
      tailP[1] * H - hipsPos.y,
      tailP[2] * H - hipsPos.z
    );
    root.userData.tailBone = tailBone;
  } else if (rigType === 'spine_flex') {
    // 5-Bone Vertical Flexible Chain (with compact symmetric side anchors)
    worldPos.set('Hips', new THREE.Vector3(0, 0.12 * H, 0));
    worldPos.set('Spine', new THREE.Vector3(0, 0.34 * H, 0));
    worldPos.set('Chest', new THREE.Vector3(0, 0.56 * H, 0));
    worldPos.set('Neck', new THREE.Vector3(0, 0.76 * H, 0));
    worldPos.set('Head', new THREE.Vector3(0, 0.92 * H, 0));

    worldPos.set('LeftShoulder', new THREE.Vector3(0.05 * H, 0.56 * H, 0));
    worldPos.set('LeftArm', new THREE.Vector3(0.10 * H, 0.56 * H, 0));
    worldPos.set('LeftForeArm', new THREE.Vector3(0.15 * H, 0.52 * H, 0));
    worldPos.set('LeftHand', new THREE.Vector3(0.18 * H, 0.48 * H, 0));

    worldPos.set('RightShoulder', new THREE.Vector3(-0.05 * H, 0.56 * H, 0));
    worldPos.set('RightArm', new THREE.Vector3(-0.10 * H, 0.56 * H, 0));
    worldPos.set('RightForeArm', new THREE.Vector3(-0.15 * H, 0.52 * H, 0));
    worldPos.set('RightHand', new THREE.Vector3(-0.18 * H, 0.48 * H, 0));

    worldPos.set('LeftUpLeg', new THREE.Vector3(0.05 * H, 0.10 * H, 0));
    worldPos.set('LeftLeg', new THREE.Vector3(0.05 * H, 0.05 * H, 0));
    worldPos.set('LeftFoot', new THREE.Vector3(0.05 * H, 0.02 * H, 0));

    worldPos.set('RightUpLeg', new THREE.Vector3(-0.05 * H, 0.10 * H, 0));
    worldPos.set('RightLeg', new THREE.Vector3(-0.05 * H, 0.05 * H, 0));
    worldPos.set('RightFoot', new THREE.Vector3(-0.05 * H, 0.02 * H, 0));
  } else {
    // Standard 19-Bone Humanoid fitted to silhouette landmarks
    const shX = landmarks.shoulderSpanX * H;
    const shY = landmarks.shoulderY * H;
    const elbX = landmarks.elbowPos[0] * H;
    const elbY = landmarks.elbowPos[1] * H;
    const elbZ = landmarks.elbowPos[2] * H;
    const wriX = landmarks.wristPos[0] * H;
    const wriY = landmarks.wristPos[1] * H;
    const wriZ = landmarks.wristPos[2] * H;

    const hipX = landmarks.hipSpanX * H;
    const hipY = landmarks.hipsY * H;
    const kneX = landmarks.kneePos[0] * H;
    const kneY = landmarks.kneePos[1] * H;
    const kneZ = landmarks.kneePos[2] * H;
    const ankX = landmarks.anklePos[0] * H;
    const ankY = landmarks.anklePos[1] * H;
    const ankZ = landmarks.anklePos[2] * H;

    worldPos.set('Hips', new THREE.Vector3(0, hipY, 0));
    worldPos.set('Spine', new THREE.Vector3(0, landmarks.spineY * H, 0));
    worldPos.set('Chest', new THREE.Vector3(0, landmarks.chestY * H, 0));
    worldPos.set('Neck', new THREE.Vector3(0, landmarks.neckY * H, 0));
    worldPos.set('Head', new THREE.Vector3(0, landmarks.headY * H, 0));

    worldPos.set('LeftShoulder', new THREE.Vector3(shX * 0.45, shY, 0));
    worldPos.set('LeftArm', new THREE.Vector3(shX, shY, 0));
    worldPos.set('LeftForeArm', new THREE.Vector3(elbX, elbY, elbZ));
    worldPos.set('LeftHand', new THREE.Vector3(wriX, wriY, wriZ));

    worldPos.set('RightShoulder', new THREE.Vector3(-shX * 0.45, shY, 0));
    worldPos.set('RightArm', new THREE.Vector3(-shX, shY, 0));
    worldPos.set('RightForeArm', new THREE.Vector3(-elbX, elbY, elbZ));
    worldPos.set('RightHand', new THREE.Vector3(-wriX, wriY, wriZ));

    worldPos.set('LeftUpLeg', new THREE.Vector3(hipX, hipY * 0.94, 0));
    worldPos.set('LeftLeg', new THREE.Vector3(kneX, kneY, kneZ));
    worldPos.set('LeftFoot', new THREE.Vector3(ankX, ankY, ankZ));

    worldPos.set('RightUpLeg', new THREE.Vector3(-hipX, hipY * 0.94, 0));
    worldPos.set('RightLeg', new THREE.Vector3(-kneX, kneY, kneZ));
    worldPos.set('RightFoot', new THREE.Vector3(-ankX, ankY, ankZ));
  }

  // Hierarchy definition
  const hierarchy: Array<{ name: HumanoidBone; parent?: HumanoidBone; quadAlias?: string }> = [
    { name: 'Hips', quadAlias: 'pelvis_hips' },
    { name: 'Spine', parent: 'Hips', quadAlias: 'spine_body' },
    { name: 'Chest', parent: 'Spine', quadAlias: 'chest_front' },
    { name: 'Neck', parent: 'Chest', quadAlias: 'neck_joint' },
    { name: 'Head', parent: 'Neck', quadAlias: 'head_joint' },

    { name: 'LeftShoulder', parent: 'Chest', quadAlias: 'front_left_shoulder' },
    { name: 'LeftArm', parent: 'LeftShoulder', quadAlias: 'front_left_leg' },
    { name: 'LeftForeArm', parent: 'LeftArm', quadAlias: 'front_left_knee' },
    { name: 'LeftHand', parent: 'LeftForeArm', quadAlias: 'front_left_paw' },

    { name: 'RightShoulder', parent: 'Chest', quadAlias: 'front_right_shoulder' },
    { name: 'RightArm', parent: 'RightShoulder', quadAlias: 'front_right_leg' },
    { name: 'RightForeArm', parent: 'RightArm', quadAlias: 'front_right_knee' },
    { name: 'RightHand', parent: 'RightForeArm', quadAlias: 'front_right_paw' },

    { name: 'LeftUpLeg', parent: 'Hips', quadAlias: 'back_left_leg' },
    { name: 'LeftLeg', parent: 'LeftUpLeg', quadAlias: 'back_left_shin' },
    { name: 'LeftFoot', parent: 'LeftLeg', quadAlias: 'back_left_paw' },

    { name: 'RightUpLeg', parent: 'Hips', quadAlias: 'back_right_leg' },
    { name: 'RightLeg', parent: 'RightUpLeg', quadAlias: 'back_right_shin' },
    { name: 'RightFoot', parent: 'RightLeg', quadAlias: 'back_right_paw' },
  ];

  for (const item of hierarchy) {
    parentMap.set(item.name, item.parent);
    const bone = new THREE.Bone();
    bone.name = item.name;
    if (rigType === 'quadruped' && item.quadAlias) {
      bone.userData.partName = item.quadAlias;
      bone.userData.role = item.quadAlias;
    }

    const wPos = worldPos.get(item.name)!;
    if (item.parent) {
      const pPos = worldPos.get(item.parent)!;
      bone.position.copy(wPos).sub(pPos);
    } else {
      bone.position.copy(wPos);
    }

    bonesMap.set(item.name, bone);
    restPositions.set(item.name, bone.position.clone());
    restRotations.set(item.name, bone.quaternion.clone());
    bonesList.push(bone);
  }

  for (const item of hierarchy) {
    const bone = bonesMap.get(item.name)!;
    if (item.parent) {
      bonesMap.get(item.parent)!.add(bone);
    } else {
      root.add(bone);
    }
  }

  // Attach tail bone for quadrupeds if present
  if (rigType === 'quadruped' && root.userData.tailBone) {
    const tailBone = root.userData.tailBone as THREE.Bone;
    bonesMap.get('Hips')!.add(tailBone);
    bonesList.push(tailBone);
  }

  root.updateMatrixWorld(true);
  const skeleton = new THREE.Skeleton(bonesList);

  // Build volumetric capsule segments for vertex weight skinning
  const idxOf = (b: HumanoidBone) => bonesList.indexOf(bonesMap.get(b)!);
  const pOf = (b: HumanoidBone) => worldPos.get(b)!.clone();

  const segments: BoneSegmentDef[] = [
    // Torso & Head
    {
      boneIndex: idxOf('Hips'),
      boneName: 'Hips',
      start: pOf('Hips').add(new THREE.Vector3(0, -0.04 * H, 0)),
      end: pOf('Spine'),
      radius: 0.14 * H,
      side: 'center',
      region: 'torso',
    },
    {
      boneIndex: idxOf('Spine'),
      boneName: 'Spine',
      start: pOf('Spine'),
      end: pOf('Chest'),
      radius: 0.14 * H,
      side: 'center',
      region: 'torso',
    },
    {
      boneIndex: idxOf('Chest'),
      boneName: 'Chest',
      start: pOf('Chest'),
      end: pOf('Neck'),
      radius: 0.15 * H,
      side: 'center',
      region: 'torso',
    },
    {
      boneIndex: idxOf('Neck'),
      boneName: 'Neck',
      start: pOf('Neck'),
      end: pOf('Head'),
      radius: 0.08 * H,
      side: 'center',
      region: 'head',
    },
    {
      boneIndex: idxOf('Head'),
      boneName: 'Head',
      start: pOf('Head'),
      end: pOf('Head').add(new THREE.Vector3(0, 0.11 * H, 0)),
      radius: 0.14 * H,
      side: 'center',
      region: 'head',
    },
    ...(rigType === 'spine_flex'
      ? []
      : ([
          // Left Arm
          {
            boneIndex: idxOf('LeftShoulder'),
            boneName: 'LeftShoulder' as HumanoidBone,
            start: pOf('LeftShoulder'),
            end: pOf('LeftArm'),
            radius: 0.075 * H,
            side: 'left' as const,
            region: 'arm' as const,
          },
          {
            boneIndex: idxOf('LeftArm'),
            boneName: 'LeftArm' as HumanoidBone,
            start: pOf('LeftArm'),
            end: pOf('LeftForeArm'),
            radius: 0.07 * H,
            side: 'left' as const,
            region: 'arm' as const,
          },
          {
            boneIndex: idxOf('LeftForeArm'),
            boneName: 'LeftForeArm' as HumanoidBone,
            start: pOf('LeftForeArm'),
            end: pOf('LeftHand'),
            radius: 0.065 * H,
            side: 'left' as const,
            region: 'arm' as const,
          },
          {
            boneIndex: idxOf('LeftHand'),
            boneName: 'LeftHand' as HumanoidBone,
            start: pOf('LeftHand'),
            end: pOf('LeftHand').add(
              pOf('LeftHand').sub(pOf('LeftForeArm')).normalize().multiplyScalar(0.06 * H)
            ),
            radius: 0.065 * H,
            side: 'left' as const,
            region: 'arm' as const,
          },

          // Right Arm
          {
            boneIndex: idxOf('RightShoulder'),
            boneName: 'RightShoulder' as HumanoidBone,
            start: pOf('RightShoulder'),
            end: pOf('RightArm'),
            radius: 0.075 * H,
            side: 'right' as const,
            region: 'arm' as const,
          },
          {
            boneIndex: idxOf('RightArm'),
            boneName: 'RightArm' as HumanoidBone,
            start: pOf('RightArm'),
            end: pOf('RightForeArm'),
            radius: 0.07 * H,
            side: 'right' as const,
            region: 'arm' as const,
          },
          {
            boneIndex: idxOf('RightForeArm'),
            boneName: 'RightForeArm' as HumanoidBone,
            start: pOf('RightForeArm'),
            end: pOf('RightHand'),
            radius: 0.065 * H,
            side: 'right' as const,
            region: 'arm' as const,
          },
          {
            boneIndex: idxOf('RightHand'),
            boneName: 'RightHand' as HumanoidBone,
            start: pOf('RightHand'),
            end: pOf('RightHand').add(
              pOf('RightHand').sub(pOf('RightForeArm')).normalize().multiplyScalar(0.06 * H)
            ),
            radius: 0.065 * H,
            side: 'right' as const,
            region: 'arm' as const,
          },

          // Left Leg
          {
            boneIndex: idxOf('LeftUpLeg'),
            boneName: 'LeftUpLeg' as HumanoidBone,
            start: pOf('LeftUpLeg'),
            end: pOf('LeftLeg'),
            radius: 0.085 * H,
            side: 'left' as const,
            region: 'leg' as const,
          },
          {
            boneIndex: idxOf('LeftLeg'),
            boneName: 'LeftLeg' as HumanoidBone,
            start: pOf('LeftLeg'),
            end: pOf('LeftFoot'),
            radius: 0.075 * H,
            side: 'left' as const,
            region: 'leg' as const,
          },
          {
            boneIndex: idxOf('LeftFoot'),
            boneName: 'LeftFoot' as HumanoidBone,
            start: pOf('LeftFoot'),
            end: pOf('LeftFoot').add(new THREE.Vector3(0, -0.04 * H, 0.06 * H)),
            radius: 0.08 * H,
            side: 'left' as const,
            region: 'leg' as const,
          },

          // Right Leg
          {
            boneIndex: idxOf('RightUpLeg'),
            boneName: 'RightUpLeg' as HumanoidBone,
            start: pOf('RightUpLeg'),
            end: pOf('RightLeg'),
            radius: 0.085 * H,
            side: 'right' as const,
            region: 'leg' as const,
          },
          {
            boneIndex: idxOf('RightLeg'),
            boneName: 'RightLeg' as HumanoidBone,
            start: pOf('RightLeg'),
            end: pOf('RightFoot'),
            radius: 0.075 * H,
            side: 'right' as const,
            region: 'leg' as const,
          },
          {
            boneIndex: idxOf('RightFoot'),
            boneName: 'RightFoot' as HumanoidBone,
            start: pOf('RightFoot'),
            end: pOf('RightFoot').add(new THREE.Vector3(0, -0.04 * H, 0.06 * H)),
            radius: 0.08 * H,
            side: 'right' as const,
            region: 'leg' as const,
          },
        ] as BoneSegmentDef[])),
  ];

  if (rigType === 'quadruped' && root.userData.tailBone) {
    const tailBone = root.userData.tailBone as THREE.Bone;
    const tailIdx = bonesList.indexOf(tailBone);
    const tailP = landmarks.quadTailPos ?? [0, 0.56, -0.45];
    segments.push({
      boneIndex: tailIdx,
      boneName: 'Hips',
      start: pOf('Hips'),
      end: new THREE.Vector3(tailP[0] * H, tailP[1] * H, tailP[2] * H),
      radius: 0.075 * H,
      side: 'center',
      region: 'torso',
    });
  }

  root.userData.isAutoRiggedGlb = true;
  root.userData.autoRigType = rigType;
  root.userData.rigLandmarks = landmarks;
  root.userData.naturalWristX = landmarks.wristPos[0];
  root.userData.naturalAnkleX = landmarks.anklePos[0];

  const rig: HumanoidRig = {
    root,
    skeleton,
    bones: bonesMap,
    restPositions,
    restRotations,
    height: H,
  };

  return { rig, segments };
}

/**
 * Computes shortest distance squared from point `p` to line segment `[a, b]`.
 */
function distToSegmentSq(p: THREE.Vector3, a: THREE.Vector3, b: THREE.Vector3): number {
  const abX = b.x - a.x;
  const abY = b.y - a.y;
  const abZ = b.z - a.z;
  const lenSq = abX * abX + abY * abY + abZ * abZ;
  if (lenSq < 1e-8) {
    const dx = p.x - a.x;
    const dy = p.y - a.y;
    const dz = p.z - a.z;
    return dx * dx + dy * dy + dz * dz;
  }
  let t = ((p.x - a.x) * abX + (p.y - a.y) * abY + (p.z - a.z) * abZ) / lenSq;
  if (t < 0) t = 0;
  else if (t > 1) t = 1;
  const cx = a.x + t * abX - p.x;
  const cy = a.y + t * abY - p.y;
  const cz = a.z + t * abZ - p.z;
  return cx * cx + cy * cy + cz * cz;
}

/**
 * Computes 4-bone volumetric skinning weights (`skinIndex` + `skinWeight`) and converts
 * static `THREE.Mesh` children inside `sceneRoot` into `THREE.SkinnedMesh` bound to `rig.skeleton`.
 */
function skinSceneMeshesToRig(
  sceneRoot: THREE.Group,
  rig: HumanoidRig,
  segments: BoneSegmentDef[],
  rigType: ResolvedRigType,
  landmarks: RigLandmarks
): number {
  sceneRoot.updateMatrixWorld(true);
  rig.root.updateMatrixWorld(true);

  const invRootMat = new THREE.Matrix4().copy(sceneRoot.matrixWorld).invert();
  const H = Math.max(0.001, rig.height);
  const armSeamX = landmarks.shoulderSpanX * 0.88 * H;
  const hipsHeight = landmarks.hipsY * H;

  const meshesToConvert: THREE.Mesh[] = [];
  sceneRoot.traverse((child) => {
    if (
      (child as THREE.Mesh).isMesh &&
      !(child as THREE.SkinnedMesh).isSkinnedMesh &&
      !child.name.startsWith('__')
    ) {
      meshesToConvert.push(child as THREE.Mesh);
    }
  });

  let skinnedCount = 0;
  const vLocal = new THREE.Vector3();
  const vModel = new THREE.Vector3();
  const skinCacheKey = `${rigType}::${H.toFixed(3)}::${JSON.stringify(landmarks)}`;

  for (const mesh of meshesToConvert) {
    const srcGeom = mesh.geometry;
    const geom = srcGeom ? srcGeom.clone() : null;
    const posAttr = geom?.attributes?.position;
    if (!geom || !posAttr || posAttr.count === 0) continue;

    const cachedSkin = srcGeom?.userData?.__cachedAutoSkin as
      | { key: string; skinIndexAttr: THREE.Uint16BufferAttribute; skinWeightAttr: THREE.Float32BufferAttribute }
      | undefined;

    if (cachedSkin && cachedSkin.key === skinCacheKey && cachedSkin.skinIndexAttr.count === posAttr.count) {
      geom.setAttribute('skinIndex', cachedSkin.skinIndexAttr);
      geom.setAttribute('skinWeight', cachedSkin.skinWeightAttr);
    } else {
      const meshToModel = new THREE.Matrix4().multiplyMatrices(invRootMat, mesh.matrixWorld);
      const vCount = posAttr.count;
      const skinIndices = new Uint16Array(vCount * 4);
      const skinWeights = new Float32Array(vCount * 4);

      for (let i = 0; i < vCount; i++) {
        vLocal.fromBufferAttribute(posAttr, i);
        vModel.copy(vLocal).applyMatrix4(meshToModel);

        // Find top 4 influencing bones using topology-aware capsule envelope weights
        let b0 = 0, b1 = 0, b2 = 0, b3 = 0;
        let w0 = 0, w1 = 0, w2 = 0, w3 = 0;

        for (let s = 0; s < segments.length; s++) {
          const seg = segments[s];

          // 1. Sagittal Left/Right Anti-Cross-Bleed Gate
          let penalty = 1.0;
          if (seg.side === 'left' && vModel.x < -0.012 * H) {
            penalty *= 0.002;
          } else if (seg.side === 'right' && vModel.x > 0.012 * H) {
            penalty *= 0.002;
          }

          // 2. Humanoid Arm vs Torso/Thigh Separation Gate
          if (rigType === 'humanoid') {
            const absX = Math.abs(vModel.x);
            if (seg.region === 'arm' && absX < armSeamX * 0.78) {
              penalty *= 0.02;
            } else if (seg.region === 'torso' && absX > armSeamX * 1.15 && vModel.y < landmarks.shoulderY * H) {
              penalty *= 0.08;
            } else if (seg.region === 'leg' && vModel.y > hipsHeight * 1.06) {
              penalty *= 0.01;
            } else if (seg.region === 'head' && vModel.y < (landmarks.neckY - 0.05) * H) {
              penalty *= 0.005;
            }
          }

          const dSq = distToSegmentSq(vModel, seg.start, seg.end);
          const rSq = seg.radius * seg.radius;
          const normalizedDistSq = dSq / Math.max(1e-6, rSq);
          const denomBase = 1.0 + normalizedDistSq * 1.35;
          const denomSq = denomBase * denomBase;
          const weight = (1.0 / (denomSq * Math.sqrt(denomBase))) * penalty;

          // Accumulate if same boneIndex already in top 4
          if (w0 > 0 && b0 === seg.boneIndex) {
            w0 = Math.max(w0, weight);
            continue;
          }
          if (w1 > 0 && b1 === seg.boneIndex) {
            w1 = Math.max(w1, weight);
            continue;
          }

          if (weight > w0) {
            b3 = b2; w3 = w2;
            b2 = b1; w2 = w1;
            b1 = b0; w1 = w0;
            b0 = seg.boneIndex; w0 = weight;
          } else if (weight > w1) {
            b3 = b2; w3 = w2;
            b2 = b1; w2 = w1;
            b1 = seg.boneIndex; w1 = weight;
          } else if (weight > w2) {
            b3 = b2; w3 = w2;
            b2 = seg.boneIndex; w2 = weight;
          } else if (weight > w3) {
            b3 = seg.boneIndex; w3 = weight;
          }
        }

        const sum = w0 + w1 + w2 + w3;
        const base = i * 4;
        if (sum > 1e-8) {
          const invSum = 1.0 / sum;
          skinIndices[base] = b0;
          skinIndices[base + 1] = b1;
          skinIndices[base + 2] = b2;
          skinIndices[base + 3] = b3;
          skinWeights[base] = w0 * invSum;
          skinWeights[base + 1] = w1 * invSum;
          skinWeights[base + 2] = w2 * invSum;
          skinWeights[base + 3] = w3 * invSum;
        } else {
          skinIndices[base] = 0;
          skinWeights[base] = 1.0;
        }
      }

      const skinIndexAttr = new THREE.Uint16BufferAttribute(skinIndices, 4);
      const skinWeightAttr = new THREE.Float32BufferAttribute(skinWeights, 4);
      geom.setAttribute('skinIndex', skinIndexAttr);
      geom.setAttribute('skinWeight', skinWeightAttr);
      if (srcGeom) {
        srcGeom.userData = srcGeom.userData || {};
        srcGeom.userData.__cachedAutoSkin = {
          key: skinCacheKey,
          skinIndexAttr,
          skinWeightAttr,
        };
      }
    }

    const skinnedMesh = new THREE.SkinnedMesh(geom, mesh.material);
    skinnedMesh.name = mesh.name || `SkinnedMesh_${skinnedCount}`;
    skinnedMesh.position.copy(mesh.position);
    skinnedMesh.quaternion.copy(mesh.quaternion);
    skinnedMesh.scale.copy(mesh.scale);
    skinnedMesh.castShadow = true;
    skinnedMesh.receiveShadow = true;
    skinnedMesh.frustumCulled = false;
    // CRITICAL PERFORMANCE INVARIANT:
    // Disable Three.js's O(N_triangles) CPU bone-skinning raycast on high-poly Image-to-3D meshes!
    // Stage selection & dragging use the fast 12-segment `__actor_hit_proxy__` cylinder instead.
    skinnedMesh.raycast = () => {};
    skinnedMesh.userData = { ...mesh.userData, isAutoSkinned: true };

    if (mesh.parent) {
      const parent = mesh.parent;
      parent.add(skinnedMesh);
      parent.remove(mesh);
    }

    skinnedMesh.updateMatrixWorld(true);
    skinnedMesh.bind(rig.skeleton, skinnedMesh.matrixWorld);
    skinnedCount++;
  }

  return skinnedCount;
}

/**
 * Creates a live-updating 3D Skeleton & Joint Overlay (`__auto_rig_skeleton_helper__`)
 * that renders bones and joints on top of the mesh when `showBones` is enabled.
 */
export function createRigVisualOverlay(rig: HumanoidRig, visible = false): THREE.Group {
  const overlayGroup = new THREE.Group();
  overlayGroup.name = '__auto_rig_skeleton_helper__';
  overlayGroup.visible = visible;

  const jointGeo = new THREE.SphereGeometry(Math.max(0.035, rig.height * 0.014), 10, 10);
  const rootJointMat = new THREE.MeshBasicMaterial({
    color: 0xf59e0b,
    depthTest: false,
    transparent: true,
    opacity: 0.95,
  });
  const limbJointMat = new THREE.MeshBasicMaterial({
    color: 0x38bdf8,
    depthTest: false,
    transparent: true,
    opacity: 0.9,
  });

  // Attach small joint spheres directly to each bone so they follow all FK/IK motion automatically
  for (const [boneName, bone] of rig.bones.entries()) {
    const existingSphere = bone.getObjectByName('__bone_joint_sphere__');
    if (existingSphere) bone.remove(existingSphere);

    const isCore = boneName === 'Hips' || boneName === 'Chest' || boneName === 'Head';
    const sphere = new THREE.Mesh(jointGeo, isCore ? rootJointMat : limbJointMat);
    sphere.name = '__bone_joint_sphere__';
    sphere.userData = { isBoneJointSphere: true, boneName };
    sphere.renderOrder = 999;
    sphere.visible = visible;
    sphere.layers.enable(0);
    sphere.layers.enable(1); // Editor gizmo layer 1 on stage + layer 0 in 3D Studio preview
    bone.add(sphere);
  }

  // Bone connection line segments updated dynamically
  const bonePairs: Array<[THREE.Bone, THREE.Bone]> = [];
  rig.skeleton.bones.forEach((bone) => {
    bone.children.forEach((child) => {
      if ((child as THREE.Bone).isBone) {
        bonePairs.push([bone, child as THREE.Bone]);
      }
    });
  });

  const positions = new Float32Array(bonePairs.length * 6);
  const lineGeo = new THREE.BufferGeometry();
  lineGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const lineMat = new THREE.LineBasicMaterial({
    color: 0x10b981,
    depthTest: false,
    transparent: true,
    opacity: 0.9,
  });
  const lineSegments = new THREE.LineSegments(lineGeo, lineMat);
  lineSegments.name = '__bone_connector_lines__';
  lineSegments.renderOrder = 998;
  lineSegments.frustumCulled = false;
  lineSegments.raycast = () => {};
  lineSegments.layers.enable(0);
  lineSegments.layers.enable(1);

  const pA = new THREE.Vector3();
  const pB = new THREE.Vector3();
  const invRoot = new THREE.Matrix4();

  const updateLines = () => {
    if (!overlayGroup.visible) return;
    invRoot.copy(rig.root.matrixWorld).invert();
    const posAttr = lineGeo.getAttribute('position') as THREE.BufferAttribute;
    for (let i = 0; i < bonePairs.length; i++) {
      const [bA, bB] = bonePairs[i];
      bA.getWorldPosition(pA).applyMatrix4(invRoot);
      bB.getWorldPosition(pB).applyMatrix4(invRoot);
      posAttr.setXYZ(i * 2, pA.x, pA.y, pA.z);
      posAttr.setXYZ(i * 2 + 1, pB.x, pB.y, pB.z);
    }
    posAttr.needsUpdate = true;
  };

  lineSegments.onBeforeRender = updateLines;
  overlayGroup.add(lineSegments);
  overlayGroup.userData.updateLines = updateLines;

  rig.root.add(overlayGroup);
  return overlayGroup;
}

/**
 * Toggles the visibility of the 3D Skeleton / Bone Overlay on an auto-rigged root group.
 */
export function setRigOverlayVisible(rootGroup: THREE.Object3D, visible: boolean, enableLayer0 = false): void {
  rootGroup.traverse((child) => {
    if (child.name === '__auto_rig_skeleton_helper__' || child.name === '__bone_joint_sphere__' || child.name === '__bone_connector_lines__') {
      child.visible = visible;
      if (enableLayer0) {
        child.layers.enable(0);
      }
      if (typeof child.userData?.updateLines === 'function') {
        child.userData.updateLines();
      }
    }
  });
}

/**
 * Checks if a loaded GLTF scene already contains an native `THREE.SkinnedMesh` with humanoid bones,
 * and if so maps them into a `HumanoidRig`.
 */
function tryExtractNativeGltfRig(sceneRoot: THREE.Group, height: number): HumanoidRig | null {
  let nativeSkinnedMesh: THREE.SkinnedMesh | null = null;
  const indexedBones: { bone: THREE.Bone; normName: string; shortName: string }[] = [];
  const mixamoBones = new Map<string, THREE.Bone>();
  const mixamoRestRotations = new Map<string, THREE.Quaternion>();
  const mixamoCharSpaceRestRotations = new Map<string, THREE.Quaternion>();

  sceneRoot.updateMatrixWorld(true);
  const invRootWorldQuat = new THREE.Quaternion();
  sceneRoot.getWorldQuaternion(invRootWorldQuat).invert();

  sceneRoot.traverse((child) => {
    if (!nativeSkinnedMesh && (child as THREE.SkinnedMesh).isSkinnedMesh && !child.userData?.isAutoSkinned) {
      nativeSkinnedMesh = child as THREE.SkinnedMesh;
    }
    if ((child as THREE.Bone).isBone) {
      const bone = child as THREE.Bone;
      const shortName = String(bone.name ?? '').replace(/^mixamorig:?/i, '').trim();
      indexedBones.push({
        bone,
        normName: normalizeBoneName(bone.name),
        shortName,
      });
      if (shortName && !mixamoBones.has(shortName)) {
        mixamoBones.set(shortName, bone);
        mixamoRestRotations.set(shortName, bone.quaternion.clone());
        const boneWorldQuat = new THREE.Quaternion();
        bone.getWorldQuaternion(boneWorldQuat);
        mixamoCharSpaceRestRotations.set(
          shortName,
          invRootWorldQuat.clone().multiply(boneWorldQuat)
        );
      }
    }
  });

  if (!nativeSkinnedMesh || indexedBones.length < 5) return null;

  const bonesMap = new Map<HumanoidBone, THREE.Bone>();
  const restPositions = new Map<HumanoidBone, THREE.Vector3>();
  const restRotations = new Map<HumanoidBone, THREE.Quaternion>();

  const candidateLookup: Record<HumanoidBone, string[]> = {
    Hips: ['mixamorighips', 'hips', 'pelvis'],
    Spine: ['mixamorigspine', 'spine'],
    Chest: ['mixamorigspine1', 'mixamorigspine2', 'chest'],
    Neck: ['mixamorigneck', 'neck'],
    Head: ['mixamorighead', 'head'],
    LeftShoulder: ['mixamorigleftshoulder', 'leftshoulder', 'lshoulder'],
    LeftArm: ['mixamorigleftarm', 'leftarm', 'larm', 'leftupperarm'],
    LeftForeArm: ['mixamorigleftforearm', 'leftforearm', 'lforearm', 'leftelbow'],
    LeftHand: ['mixamoriglefthand', 'lefthand', 'lhand', 'leftwrist'],
    RightShoulder: ['mixamorigrightshoulder', 'rightshoulder', 'rshoulder'],
    RightArm: ['mixamorigrightarm', 'rightarm', 'rarm', 'rightupperarm'],
    RightForeArm: ['mixamorigrightforearm', 'rightforearm', 'rforearm', 'rightelbow'],
    RightHand: ['mixamorigrighthand', 'righthand', 'rhand', 'rightwrist'],
    LeftUpLeg: ['mixamorigleftupleg', 'leftupleg', 'lupleg', 'leftthigh', 'lefthip'],
    LeftLeg: ['mixamorigleftleg', 'leftleg', 'lleg', 'leftshin', 'leftknee'],
    LeftFoot: ['mixamorigleftfoot', 'leftfoot', 'lfoot', 'leftankle'],
    RightUpLeg: ['mixamorigrightupleg', 'rightupleg', 'rupleg', 'rightthigh', 'righthip'],
    RightLeg: ['mixamorigrightleg', 'rightleg', 'rleg', 'rightshin', 'rightknee'],
    RightFoot: ['mixamorigrightfoot', 'rightfoot', 'rfoot', 'rightankle'],
  };

  for (const boneName of HUMANOID_BONES) {
    const candidates = candidateLookup[boneName] || [boneName.toLowerCase()];
    let matchedBone: THREE.Bone | null = null;
    for (const cand of candidates) {
      const normCand = normalizeBoneName(cand);
      const match = indexedBones.find(
        (b) => b.normName === normCand || b.normName.endsWith(normCand)
      );
      if (match) {
        matchedBone = match.bone;
        break;
      }
    }
    if (matchedBone) {
      bonesMap.set(boneName, matchedBone);
      restPositions.set(boneName, matchedBone.position.clone());
      restRotations.set(boneName, matchedBone.quaternion.clone());
    }
  }

  if (bonesMap.size < 5) return null;

  return {
    root: sceneRoot,
    skeleton: (nativeSkinnedMesh as THREE.SkinnedMesh).skeleton,
    bones: bonesMap,
    restPositions,
    restRotations,
    mixamoBones: mixamoBones.size >= 15 ? mixamoBones : undefined,
    mixamoRestRotations: mixamoBones.size >= 15 ? mixamoRestRotations : undefined,
    mixamoCharSpaceRestRotations: mixamoBones.size >= 15 ? mixamoCharSpaceRestRotations : undefined,
    height,
  };
}

/**
 * Main Entry Point: Automatically rigs a `.GLB` / `THREE.Group` scene in-place.
 *
 * - If the model is `humanoid`, `quadruped`, or `spine_flex`, fits a skeleton to the
 *   mesh silhouette (or user-adjusted `landmarks`), skins all static meshes to the skeleton,
 *   and attaches `rig` + `boneOverlayGroup` to `sceneRoot`.
 * - If the model is `rigid_prop`, preserves 100% rigid hard-surface geometry while setting up
 *   hand-socket grip metadata and sub-part articulation tags.
 */
export function autoRigGltfScene(
  sceneRoot: THREE.Group,
  options: AutoRigOptions = {}
): AutoRigResult {
  // 0. If re-rigging a previously auto-rigged scene, clean up old auto-generated bones & overlays first.
  // Collect targets into arrays BEFORE mutating parent.children so traversal indices never shift mid-loop.
  const staleRigObjects: THREE.Object3D[] = [];
  const autoSkinnedToRevert: THREE.SkinnedMesh[] = [];
  sceneRoot.traverse((child) => {
    if (
      child !== sceneRoot &&
      (child.name === 'AutoRiggedRoot' || child.name === '__auto_rig_skeleton_helper__')
    ) {
      staleRigObjects.push(child);
    } else if ((child as THREE.SkinnedMesh).isSkinnedMesh && child.userData?.isAutoSkinned) {
      autoSkinnedToRevert.push(child as THREE.SkinnedMesh);
    }
  });

  for (const staleObj of staleRigObjects) {
    if (staleObj.parent) {
      staleObj.parent.remove(staleObj);
    }
  }

  for (const sm of autoSkinnedToRevert) {
    // Revert SkinnedMesh back to standard Mesh with clean geometry before re-binding
    const plainGeom = sm.geometry ? sm.geometry.clone() : new THREE.BufferGeometry();
    plainGeom.deleteAttribute('skinIndex');
    plainGeom.deleteAttribute('skinWeight');
    if (sm.geometry?.userData?.__cachedAutoSkin) {
      plainGeom.userData = {
        ...plainGeom.userData,
        __cachedAutoSkin: sm.geometry.userData.__cachedAutoSkin,
      };
    }
    const plainMesh = new THREE.Mesh(plainGeom, sm.material);
    plainMesh.name = sm.name;
    plainMesh.position.copy(sm.position);
    plainMesh.quaternion.copy(sm.quaternion);
    plainMesh.scale.copy(sm.scale);
    plainMesh.castShadow = true;
    plainMesh.receiveShadow = true;
    const { isAutoSkinned: _removed, ...restUserData } = sm.userData || {};
    plainMesh.userData = restUserData;
    if (sm.parent) {
      sm.parent.add(plainMesh);
      sm.parent.remove(sm);
    }
  }

  sceneRoot.updateMatrixWorld(true);
  const bbox = new THREE.Box3().setFromObject(sceneRoot);
  const size = bbox.getSize(new THREE.Vector3());
  const H = Math.max(0.2, size.y || 5.06);

  const resolvedType = resolveAutoRigType(sceneRoot, options);

  // 1. Check if the GLB already has native bones (unless user explicitly customized landmarks)
  if (!options.landmarks && resolvedType === 'humanoid') {
    const nativeRig = tryExtractNativeGltfRig(sceneRoot, H);
    if (nativeRig) {
      const overlay = createRigVisualOverlay(nativeRig, Boolean(options.showBones));
      sceneRoot.userData.rig = nativeRig;
      sceneRoot.userData.autoRigType = 'humanoid';
      sceneRoot.userData.autoRigResult = {
        rigType: 'humanoid',
        rig: nativeRig,
        landmarks: DEFAULT_HUMANOID_LANDMARKS,
        boneCount: nativeRig.skeleton.bones.length,
        skinnedMeshCount: 1,
        boneOverlayGroup: overlay,
      };
      return sceneRoot.userData.autoRigResult;
    }
  }

  // 2. Rigid Prop / Vehicle / Weapon / Set Piece
  if (resolvedType === 'rigid_prop') {
    const landmarks: RigLandmarks = {
      ...DEFAULT_HUMANOID_LANDMARKS,
      detectedStance: 'rigid',
      ...options.landmarks,
    };
    // Configure grip socket origin for handheld attachment
    sceneRoot.userData.rig = null;
    sceneRoot.userData.autoRigType = 'rigid_prop';
    sceneRoot.userData.gripSocket = {
      offset: { x: 0, y: -H * 0.25, z: 0 },
      rotation: { x: 90, y: 0, z: 0 },
    };
    const res: AutoRigResult = {
      rigType: 'rigid_prop',
      rig: null,
      landmarks,
      boneCount: 0,
      skinnedMeshCount: 0,
      boneOverlayGroup: null,
    };
    sceneRoot.userData.autoRigResult = res;
    return res;
  }

  // 3. Detect silhouette landmarks & build adaptive skeleton (`humanoid`, `quadruped`, or `spine_flex`)
  const landmarks = detectMeshRigLandmarks(sceneRoot, resolvedType, options.landmarks);
  const { rig, segments } = buildAdaptiveRigSkeleton(resolvedType, H, landmarks);

  // Add the skeleton hierarchy into `sceneRoot` so it moves with the model
  sceneRoot.add(rig.root);
  sceneRoot.updateMatrixWorld(true);

  // 4. Volumetric capsule skinning (skipped during fast live slider preview to maintain 60 FPS on 400k+ vert meshes)
  const skinnedMeshCount = options.fastPreviewOnly
    ? 0
    : skinSceneMeshesToRig(sceneRoot, rig, segments, resolvedType, landmarks);

  // 5. Make `rig.root` point to `sceneRoot` so `rigPoint(rig, ...)` and `StagePrevis3D` transform calculations work seamlessly
  rig.root = sceneRoot;
  sceneRoot.userData.isAutoRiggedGlb = true;
  sceneRoot.userData.autoRigType = resolvedType;
  sceneRoot.userData.rigLandmarks = landmarks;
  sceneRoot.userData.naturalWristX = landmarks.wristPos[0];
  sceneRoot.userData.naturalAnkleX = landmarks.anklePos[0];
  sceneRoot.userData.rig = rig;

  const overlay = createRigVisualOverlay(rig, Boolean(options.showBones));

  const result: AutoRigResult = {
    rigType: resolvedType,
    rig,
    landmarks,
    boneCount: rig.skeleton.bones.length,
    skinnedMeshCount,
    boneOverlayGroup: overlay,
  };
  sceneRoot.userData.autoRigResult = result;
  return result;
}

